#include <stdio.h>

int sum(const int values[], size_t length) {
    int total = 0;
    for (size_t i = 0; i < length; i++) {
        total += values[i];
    }
    return total;
}

int main(void) {
    int values[] = {2, 4, 6};
    printf("%d\n", sum(values, sizeof values / sizeof values[0]));
    return 0;
}

#include <stdio.h>

struct Counter {
    int value;
};

void increment(struct Counter *counter) {
    counter->value += 1;
}

int main(void) {
    struct Counter tally = {0};
    increment(&tally);
    printf("%d\n", tally.value);
    return 0;
}

