#include <limits.h>
#include <stdio.h>

static int add_counts(int left, int right, int *total) {
    if (left < 0 || right < 0 || left > INT_MAX - right) return 0;
    *total = left + right;
    return 1;
}

int main(void) {
    int total;
    if (add_counts(8, 13, &total)) printf("%d\n", total);
    if (!add_counts(INT_MAX, 1, &total)) puts("out of range");
}

#include <stdio.h>

enum State { STATE_IDLE, STATE_READING, STATE_DONE };

static const char *label(enum State state) {
    switch (state) {
        case STATE_IDLE: return "idle";
        case STATE_READING: return "reading";
        case STATE_DONE: return "done";
    }
    return "unknown";
}

int main(void) {
    puts(label(STATE_READING));
}

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    FILE *source = tmpfile();
    if (source == NULL) return 1;
    if (fputs("17\n", source) == EOF || fseek(source, 0, SEEK_SET) != 0) {
        fclose(source);
        return 1;
    }
    char buffer[16];
    int read_line = fgets(buffer, sizeof buffer, source) != NULL;
    if (fclose(source) == EOF || !read_line) return 1;
    char *newline = strchr(buffer, '\n');
    if (!newline) return 1;
    *newline = '\0';
    char *end;
    errno = 0;
    long reading = strtol(buffer, &end, 10);
    if (end == buffer || *end != '\0' || errno == ERANGE) return 1;
    printf("Reading: %ld\n", reading);
}

