#include <stdio.h>
#include <stdlib.h>

static int compare_ints(const void *left, const void *right) {
    int a = *(const int *)left;
    int b = *(const int *)right;
    return (a > b) - (a < b);
}

int main(void) {
    int values[] = {17, -4, 8, 3};
    size_t count = sizeof values / sizeof values[0];
    qsort(values, count, sizeof values[0], compare_ints);
    int key = 8;
    const int *found = bsearch(&key, values, count, sizeof values[0], compare_ints);
    if (found) printf("first: %d, found: %d\n", values[0], *found);
}

#include <stdio.h>

int main(void) {
    const unsigned read = 1u << 0;
    const unsigned write = 1u << 1;
    unsigned permissions = read | write;
    permissions &= ~write;
    printf("read=%d write=%d\n", (permissions & read) != 0,
           (permissions & write) != 0);
}

