#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

static int read_count(const char *text, long *count) {
    char *end;
    errno = 0;
    long parsed = strtol(text, &end, 10);
    if (end == text || *end || errno == ERANGE || parsed < 0) return 0;
    *count = parsed;
    return 1;
}

int main(int argc, char *argv[]) {
    const char *example = argc == 2 ? argv[1] : "17";
    long count;
    if (!read_count(example, &count)) {
        fputs("invalid count\n", stderr);
        return EXIT_FAILURE;
    }
    printf("count=%ld\n", count);
    return EXIT_SUCCESS;
}
